// Monta o pedido para a API da Anthropic a partir do que chegou no webhook.
// Exemplo de corpo do webhook: { "mensagem": "...", "cliente": { "empresa": "...", "renovacao": "2026-12-15", ... } }
const SYSTEM = "Você é um agente de pós-venda de uma revenda de Microsoft 365 e Copilot.\nSua tarefa é triar cada mensagem de cliente para o time humano agir rápido.\n\nComo trabalhar:\n- Use os dados do CRM enviados junto com a mensagem: renovação próxima,\n  adoção baixa do Copilot e NPS baixo aumentam a prioridade.\n- Prioridade alta: risco de perder o cliente, cliente parado em algo urgente,\n  ou renovação em até 45 dias com sinais de insatisfação.\n- Se o cliente pedir mais licenças, preencha oportunidade_licencas com o número citado.\n- A resposta sugerida é um rascunho em português, cordial e curto (até 4 frases).\n  Não invente prazos, preços ou recursos.";
const SCHEMA = {"type": "object", "properties": {"categoria": {"type": "string", "enum": ["duvida_uso", "problema_tecnico", "financeiro", "renovacao", "oportunidade_expansao", "risco_churn"]}, "prioridade": {"type": "string", "enum": ["alta", "media", "baixa"]}, "sentimento": {"type": "string", "enum": ["positivo", "neutro", "negativo"]}, "encaminhar_para": {"type": "string", "enum": ["suporte", "customer_success", "comercial", "financeiro"]}, "resumo": {"type": "string", "description": "Resumo da mensagem em 1 frase."}, "sinais_de_risco": {"type": "array", "items": {"type": "string"}, "description": "Sinais de risco de churn (pode ser lista vazia)."}, "oportunidade_licencas": {"type": "integer", "description": "Licenças novas que o cliente sinalizou querer (0 se nenhuma)."}, "proxima_acao": {"type": "string", "description": "Ação interna recomendada."}, "resposta_sugerida": {"type": "string", "description": "Rascunho de resposta ao cliente."}, "follow_up_dias": {"type": "integer", "description": "Em quantos dias fazer follow-up."}}, "required": ["categoria", "prioridade", "sentimento", "encaminhar_para", "resumo", "sinais_de_risco", "oportunidade_licencas", "proxima_acao", "resposta_sugerida", "follow_up_dias"], "additionalProperties": false};

return $input.all().map(item => {
  const entrada = item.json.body ?? item.json;
  const pedido = {
    model: 'claude-opus-5-5',
    max_tokens: 4000,
    system: SYSTEM,
    output_config: { effort: 'low', format: { type: 'json_schema', schema: SCHEMA } },
    messages: [{
      role: 'user',
      content: `Dados do CRM: ${JSON.stringify(entrada.cliente ?? {})}\nData de hoje: ${new Date().toISOString().slice(0, 10)}\n\n<mensagem_do_cliente>\n${entrada.mensagem}\n</mensagem_do_cliente>`,
    }],
  };
  return { json: { pedido, entrada } };
});

// Lê a resposta do Claude: o JSON da triagem vem no bloco de texto.
return $input.all().map((item, i) => {
  const resposta = item.json;
  if (resposta.stop_reason === 'refusal') {
    return { json: { erro: 'O modelo recusou esta mensagem.', entrada: $('Montar pedido').all()[i].json.entrada } };
  }
  const texto = (resposta.content || []).find(b => b.type === 'text')?.text ?? '{}';
  const triagem = JSON.parse(texto);
  return { json: { ...triagem, entrada: $('Montar pedido').all()[i].json.entrada } };
});
